def main():
    print(f"MCCQE Topics Count: {len(MCCQE_TOPICS)}")
    print(f"NEET Topics Count: {len(NEET_TOPICS)}")
    print(f"MRCP Topics Count: {len(MRCP_TOPICS)}")

    assert len(MCCQE_TOPICS) == 100
    assert len(NEET_TOPICS) == 100
    assert len(MRCP_TOPICS) == 100

    for name, lst in [("MCCQE", MCCQE_TOPICS), ("NEET", NEET_TOPICS), ("MRCP", MRCP_TOPICS)]:
        for i, t in enumerate(lst):
            assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at {name} #{i}: {t[0]}"
            assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at {name} #{i}: {t[0]}"
            assert t[5].startswith("https://"), f"Invalid URL at {name} #{i}: {t[5]}"

    out_path = os.path.join(os.path.dirname(__file__), "mega112_topics.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 112 topics (MCCQE 100, NEET 100, MRCP 100)\n\n")
